### C++

```cpp
#include <bits/stdc++.h>
using namespace std;

const long long MOD1 = 1000000007LL;
const long long MOD2 = 1000000009LL;
const long long BASE = 911382323LL;

struct Key {
    int d;
    long long a, b;

    bool operator==(const Key& other) const {
        return d == other.d && a == other.a && b == other.b;
    }
};

// 自定义哈希函数
struct KeyHash {
    size_t operator()(const Key& k) const {
        long long res = k.d;
        res = res * 1000003 + k.a;
        res = res * 1000003 + k.b;
        return (size_t)(res ^ (res >> 32));
    }
};

int n, LOG = 18, timerCnt = 0;
string s;
vector<vector<int>> g;
vector<vector<int>> fa;
vector<int> dep, sz, son, dfn, rev, ans;
vector<long long> h1, h2, pow1, pow2;

// 建树，求父亲、深度、哈希、子树大小和重儿子
void build() {
    vector<int> order;
    order.push_back(1);

    for (int i = 0; i < (int)order.size(); i++) {
        int u = order[i];

        for (int v : g[u]) {
            if (v == fa[0][u]) continue;

            fa[0][v] = u;
            dep[v] = dep[u] + 1;

            int c = s[v - 1] - 'a' + 1;
            h1[v] = (h1[u] * BASE + c) % MOD1;
            h2[v] = (h2[u] * BASE + c) % MOD2;

            order.push_back(v);
        }
    }

    // 倍增父亲
    for (int k = 1; k < LOG; k++) {
        for (int i = 1; i <= n; i++) {
            fa[k][i] = fa[k - 1][fa[k - 1][i]];
        }
    }

    // 求子树大小和重儿子
    for (int i = n - 1; i >= 0; i--) {
        int u = order[i];
        sz[u] = 1;

        for (int v : g[u]) {
            if (v == fa[0][u]) continue;

            sz[u] += sz[v];
            if (son[u] == 0 || sz[v] > sz[son[u]]) {
                son[u] = v;
            }
        }
    }
}

// 求 DFS 序
void dfsDfn(int u) {
    dfn[u] = ++timerCnt;
    rev[timerCnt] = u;

    for (int v : g[u]) {
        if (v != fa[0][u]) {
            dfsDfn(v);
        }
    }
}

// 求 ancestor 的下一层到 x 的字符串哈希
Key getKey(int ancestor, int x) {
    int len = dep[x] - dep[ancestor];

    long long a = (h1[x] - h1[ancestor] * pow1[len]) % MOD1;
    if (a < 0) a += MOD1;

    long long b = (h2[x] - h2[ancestor] * pow2[len]) % MOD2;
    if (b < 0) b += MOD2;

    return {len, a, b};
}

// 递归处理答案
void dfs(int u) {
    for (int v : g[u]) {
        if (v != fa[0][u]) {
            dfs(v);
        }
    }

    unordered_map<Key, int, KeyHash> mp;

    // 先加入重儿子子树
    if (son[u]) {
        int v = son[u];

        for (int i = dfn[v]; i < dfn[v] + sz[v]; i++) {
            int x = rev[i];
            Key key = getKey(u, x);
            mp[key] = v;
        }
    }

    // 处理轻儿子子树
    for (int v : g[u]) {
        if (v == fa[0][u] || v == son[u]) continue;

        // 先查询，避免同一儿子子树内部匹配
        for (int i = dfn[v]; i < dfn[v] + sz[v]; i++) {
            int x = rev[i];
            Key key = getKey(u, x);

            if (mp.find(key) != mp.end() && mp[key] != v) {
                int d = dep[x] - dep[u];
                ans[u] = max(ans[u], 2 * d + 1);
            }
        }

        // 再加入当前儿子子树
        for (int i = dfn[v]; i < dfn[v] + sz[v]; i++) {
            int x = rev[i];
            Key key = getKey(u, x);
            mp[key] = v;
        }
    }
}

vector<int> solve() {
    pow1.assign(n + 2, 1);
    pow2.assign(n + 2, 1);

    for (int i = 1; i <= n + 1; i++) {
        pow1[i] = pow1[i - 1] * BASE % MOD1;
        pow2[i] = pow2[i - 1] * BASE % MOD2;
    }

    build();
    dfsDfn(1);

    ans.assign(n + 1, 1);
    dfs(1);

    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    cin >> s;

    g.assign(n + 1, vector<int>());

    for (int i = 1; i < n; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    fa.assign(LOG, vector<int>(n + 1, 0));
    dep.assign(n + 1, 0);
    sz.assign(n + 1, 0);
    son.assign(n + 1, 0);
    dfn.assign(n + 1, 0);
    rev.assign(n + 1, 0);
    h1.assign(n + 1, 0);
    h2.assign(n + 1, 0);

    vector<int> res = solve();

    for (int i = 1; i <= n; i++) {
        if (i > 1) cout << ' ';
        cout << res[i];
    }
    cout << '\n';

    return 0;
}
